VALUES ('doc-09-mitre-attack-p0-14482', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T21:17:07.021Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROAMINGHOUSE](https://attack.mitre.org/software/S9026) has been loaded as a Word Template file when victims opened a decoy document placed in `%APPDATA%\\Microsoft\\Templates` alongside a [ROAMINGHOUSE](https://attack.mitre.org/software/S9026) macro.(Citation: Trend Micro Earth Kasha Anel NOV 2024)", "external_references": [{"description": "Hiroaki, H. (2024, November 26). Guess Who’s Back - The Return of ANEL in the Recent Earth Kasha Spear-phishing Campaign in 2024. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha Anel NOV 2024", "url": "https://www.trendmicro.com/en_us/research/24/k/return-of-anel-in-the-recent-earth-kasha-spearphishing-campaign.html"}], "id": "relationship--1efd302f-e162-4f68-a942-f5d14b642a78", "modified": "2026-04-29T14:23:05.947Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--251f1715-fc97-4487-b939-5c8823ef7a39", "spec_version": "2.1", "target_ref": "attack-pattern--79a47ad0-fc3b-4821-9f01-a026b1ddba21", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14482', 0, 96, '09-mitre-attack', 'retrieved', 'E717E78609A1E83B8FB0512DF2E8FB950BB6A49C184B67A7E1CA849C56D71100', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
