VALUES ('doc-09-mitre-attack-p0-14490', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T19:11:59.102Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROAMINGHOUSE](https://attack.mitre.org/software/S9026) can use WMI to launch a legitimate executable later used to enable DLL sideloading.(Citation: Trend Micro Earth Kasha Updates APR 2025)(Citation: Trend Micro Earth Kasha Anel NOV 2024)", "external_references": [{"description": "Hiroaki, H. (2024, November 26). Guess Who’s Back - The Return of ANEL in the Recent Earth Kasha Spear-phishing Campaign in 2024. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha Anel NOV 2024", "url": "https://www.trendmicro.com/en_us/research/24/k/return-of-anel-in-the-recent-earth-kasha-spearphishing-campaign.html"}, {"description": "Hiroaki, H. (2025, April 30). Earth Kasha Updates TTPs in Latest Campaign Targeting Taiwan and Japan. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha Updates APR 2025", "url": "https://www.trendmicro.com/en_us/research/25/d/earth-kasha-updates-ttps.html"}], "id": "relationship--b67e0e26-717f-4aab-871c-22d9bfddc5d1", "modified": "2026-04-29T14:23:06.174Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--251f1715-fc97-4487-b939-5c8823ef7a39", "spec_version": "2.1", "target_ref": "attack-pattern--01a5a209-b94c-450b-b7f9-946497d91055", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14490', 0, 127, '09-mitre-attack', 'retrieved', 'DEE57563F134CB694D0DAE8E4BB0E8447135CEFA3ED30EB9995C7A9C0DDD40B7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
