VALUES ('doc-09-mitre-attack-p0-14491', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T19:10:24.327Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROAMINGHOUSE](https://attack.mitre.org/software/S9026) can use a legitimate EXE to sideload a malicious DLL named JSFC.dll.(Citation: Trend Micro Earth Kasha Updates APR 2025) [ROAMINGHOUSE](https://attack.mitre.org/software/S9026) has also used ScnCfg32.exe to sideload vsodscpl.dll to enable [UPPERCUT](https://attack.mitre.org/software/S0275) execution.(Citation: Trend Micro Earth Kasha Anel NOV 2024)", "external_references": [{"description": "Hiroaki, H. (2024, November 26). Guess Who’s Back - The Return of ANEL in the Recent Earth Kasha Spear-phishing Campaign in 2024. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha Anel NOV 2024", "url": "https://www.trendmicro.com/en_us/research/24/k/return-of-anel-in-the-recent-earth-kasha-spearphishing-campaign.html"}, {"description": "Hiroaki, H. (2025, April 30). Earth Kasha Updates TTPs in Latest Campaign Targeting Taiwan and Japan. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha Updates APR 2025", "url": "https://www.trendmicro.com/en_us/research/25/d/earth-kasha-updates-ttps.html"}], "id": "relationship--ded88ab1-321a-475c-9539-16e3bb292379", "modified": "2026-04-29T14:23:06.229Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--251f1715-fc97-4487-b939-5c8823ef7a39", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14491', 0, 137, '09-mitre-attack', 'retrieved', 'ABFD5A793A47C92E1242C93B9859507538AF7E1382D6D69D5FB51F0EB571A632', 'v