VALUES ('doc-09-mitre-attack-p0-14533', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-15T18:11:12.744Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TONESHELL](https://attack.mitre.org/software/S1239) has been initiated using LNK files that were programmed to display a PDF icon to entice the victim to click on the file to execute an office.exe binary.(Citation: CSIRT CTI MUSTANG PANDA PUBLOAD TONESHELL JAN 2024)", "external_references": [{"description": "CSIRT CTI. (2024, January 23). Stately Taurus Targets Myanmar Amidst Concerns over Military Junta’s Handling of Rebel Attacks. Retrieved August 4, 2025.", "source_name": "CSIRT CTI MUSTANG PANDA PUBLOAD TONESHELL JAN 2024", "url": "https://csirt-cti.net/2024/01/23/stately-taurus-targets-myanmar/"}], "id": "relationship--ec2eb361-4544-4599-88a1-ba6c13268b08", "modified": "2026-04-29T14:23:06.246Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2683fde8-1dc4-415c-94bd-9bb95cc5b7ff", "spec_version": "2.1", "target_ref": "attack-pattern--887274fc-2d63-4bdc-82f3-fae56d1d5fdc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14533', 0, 101, '09-mitre-attack', 'retrieved', '609E381CA639BD56C9F64A38AFBFF44BD251D20654FD33A878935661A29C3DD7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
