VALUES ('doc-09-mitre-attack-p0-14537', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-20T21:59:35.989Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[UPSTYLE](https://attack.mitre.org/software/S1164) encodes its main content prior to loading via Python as base64-encoded blobs.(Citation: Volexity UPSTYLE 2024)(Citation: Palo Alto MidnightEclipse APR 2024)", "external_references": [{"description": "Unit 42. (2024, April 12). Threat Brief: Operation MidnightEclipse, Post-Exploitation Activity Related to CVE-2024-3400 . Retrieved January 15, 2025.", "source_name": "Palo Alto MidnightEclipse APR 2024", "url": "https://unit42.paloaltonetworks.com/cve-2024-3400/"}, {"description": "Volexity Threat Research. (2024, April 12). Zero-Day Exploitation of Unauthenticated Remote Code Execution Vulnerability in GlobalProtect (CVE-2024-3400). Retrieved November 20, 2024.", "source_name": "Volexity UPSTYLE 2024", "url": "https://www.volexity.com/blog/2024/04/12/zero-day-exploitation-of-unauthenticated-remote-code-execution-vulnerability-in-globalprotect-cve-2024-3400/"}], "id": "relationship--1bd6e148-29c0-473e-8752-66bd01e3a629", "modified": "2026-04-29T14:23:05.942Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2692bdd0-da52-44ff-88a3-9db28b948ea2", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14537', 0, 107, '09-mitre-attack', 'retrieved', '7BB996BD3D7265F2CA7E2EFC222D8294084E987FE57880DAB159CC6D8A379D3F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
