VALUES ('doc-09-mitre-attack-p0-14584', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-17T11:49:54.485Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Medusa Ransomware](https://attack.mitre.org/software/S1244) has identified networked drives.(Citation: Palo Alto Unit 42 Medusa Group Medusa Ransomware January 2024)(Citation: Broadcom Medusa Ransomware Medusa Group March 2025)(Citation: Security Scorecard Medusa Ransomware January 2024)", "external_references": [{"description": "Anthony Galiette, Doel Santos. (2024, January 11). Medusa Ransomware Turning Your Files into Stone. Retrieved October 15, 2025.", "source_name": "Palo Alto Unit 42 Medusa Group Medusa Ransomware January 2024", "url": "https://unit42.paloaltonetworks.com/medusa-ransomware-escalation-new-leak-site/"}, {"description": "Threat Hunter Team Symantec and Carbon Black. (2025, March 6). Medusa Ransomware Activity Continues to Increase. Retrieved October 15, 2025.", "source_name": "Broadcom Medusa Ransomware Medusa Group March 2025", "url": "https://www.security.com/threat-intelligence/medusa-ransomware-attacks"}, {"description": "Vlad Pasca. (2024, January 1). A Deep Dive into Medusa Ransomware. Retrieved October 15, 2025.", "source_name": "Security Scorecard Medusa Ransomware January 2024", "url": "https://securityscorecard.com/wp-content/uploads/2024/01/deep-dive-into-medusa-ransomware.pdf"}], "id": "relationship--160fe071-f28f-47c3-a87c-e7cfc9e72f31", "modified": "2026-04-29T14:23:05.934Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--28d93902-30e7-4436-8885-6d312c51c9a3", "spec_version": "2.1", "target_ref": "attack-pattern--3489cfc5-640f-4bb3-a103-9137b97de79f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}'