VALUES ('doc-09-mitre-attack-p0-14593', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T23:05:30.153Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Medusa Ransomware](https://attack.mitre.org/software/S1244) has enumerated logical drives on infected hosts.(Citation: Security Scorecard Medusa Ransomware January 2024)", "external_references": [{"description": "Vlad Pasca. (2024, January 1). A Deep Dive into Medusa Ransomware. Retrieved October 15, 2025.", "source_name": "Security Scorecard Medusa Ransomware January 2024", "url": "https://securityscorecard.com/wp-content/uploads/2024/01/deep-dive-into-medusa-ransomware.pdf"}], "id": "relationship--68be315f-f84b-4790-892b-e284089658a8", "modified": "2026-04-29T14:23:06.067Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--28d93902-30e7-4436-8885-6d312c51c9a3", "spec_version": "2.1", "target_ref": "attack-pattern--f2514ae4-4e9b-4f26-a5ba-c4ae85fe93c3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14593', 0, 70, '09-mitre-attack', 'retrieved', '72793BDFF3E35C57AA512CFF671F1DCB38162DFB30B89E6CF0B86DEC2228A45F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
