VALUES ('doc-09-mitre-attack-p0-14669', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-12T20:31:27.096Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BUSHWALK](https://attack.mitre.org/software/S1118) can modify the `DSUserAgentCap.pm` Perl module on Ivanti Connect Secure VPNs and either activate or deactivate depending on the value of the user agent in incoming HTTP requests.(Citation: Mandiant Cutting Edge Part 3 February 2024)", "external_references": [{"description": "Lin, M. et al. (2024, February 27). Cutting Edge, Part 3: Investigating Ivanti Connect Secure VPN Exploitation and Persistence Attempts. Retrieved March 1, 2024.", "source_name": "Mandiant Cutting Edge Part 3 February 2024", "url": "https://www.mandiant.com/resources/blog/investigating-ivanti-exploitation-persistence"}], "id": "relationship--291e3bfc-90e7-44ac-828c-8bbf7b36431c", "modified": "2026-04-29T14:23:05.961Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--29a0bb87-1162-4c83-9834-2a98a876051b", "spec_version": "2.1", "target_ref": "attack-pattern--451a9977-d255-43c9-b431-66de80130c8c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14669', 0, 101, '09-mitre-attack', 'retrieved', '5CD9CEE88818ACADB5FAB36086A4BC7AA52334865BE9B2855CCAD11E62A71CD4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
