VALUES ('doc-09-mitre-attack-p0-14676', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-22T02:37:07.083Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[macOS.OSAMiner](https://attack.mitre.org/software/S1048) has checked to ensure there is enough disk space using the Unix utility `df`.(Citation: SentinelLabs reversing run-only applescripts 2021)", "external_references": [{"description": "Phil Stokes. (2021, January 11). FADE DEAD | Adventures in Reversing Malicious Run-Only AppleScripts. Retrieved September 29, 2022.", "source_name": "SentinelLabs reversing run-only applescripts 2021", "url": "https://www.sentinelone.com/labs/fade-dead-adventures-in-reversing-malicious-run-only-applescripts/"}], "id": "relationship--0f0b7154-b0d2-4aa1-b819-7d4e3dfe3bd1", "modified": "2026-04-29T14:23:05.924Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2a59a237-1530-4d55-91f9-2aebf961cc37", "spec_version": "2.1", "target_ref": "attack-pattern--f2514ae4-4e9b-4f26-a5ba-c4ae85fe93c3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14676', 0, 77, '09-mitre-attack', 'retrieved', '4B3DA715719BBC771951834ECEB66EFB8CF3BE96DE5F33E33534B10944C403E3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
