VALUES ('doc-09-mitre-attack-p0-14678', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-19T15:32:29.067Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[macOS.OSAMiner](https://attack.mitre.org/software/S1048) has used run-only Applescripts, a compiled and stripped version of [AppleScript](https://attack.mitre.org/techniques/T1059/002), to remove human readable indicators to evade detection.(Citation: SentinelLabs reversing run-only applescripts 2021)", "external_references": [{"description": "Phil Stokes. (2021, January 11). FADE DEAD | Adventures in Reversing Malicious Run-Only AppleScripts. Retrieved September 29, 2022.", "source_name": "SentinelLabs reversing run-only applescripts 2021", "url": "https://www.sentinelone.com/labs/fade-dead-adventures-in-reversing-malicious-run-only-applescripts/"}], "id": "relationship--596ef2d8-53ff-4fde-8dd2-08b53371d0da", "modified": "2026-04-29T14:23:06.047Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2a59a237-1530-4d55-91f9-2aebf961cc37", "spec_version": "2.1", "target_ref": "attack-pattern--2f41939b-54c3-41d6-8f8b-35f1ec18ed97", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14678', 0, 82, '09-mitre-attack', 'retrieved', '9D14EF4ED591169931BC9D2608360616C7D0CCB25D7BC1CB220A28D3EF3640B7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
