VALUES ('doc-09-mitre-attack-p0-14679', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-04T06:54:11.907Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[macOS.OSAMiner](https://attack.mitre.org/software/S1048) has embedded [Stripped Payloads](https://attack.mitre.org/techniques/T1027/008) within another run-only [Stripped Payloads](https://attack.mitre.org/techniques/T1027/008).(Citation: SentinelLabs reversing run-only applescripts 2021)", "external_references": [{"description": "Phil Stokes. (2021, January 11). FADE DEAD | Adventures in Reversing Malicious Run-Only AppleScripts. Retrieved September 29, 2022.", "source_name": "SentinelLabs reversing run-only applescripts 2021", "url": "https://www.sentinelone.com/labs/fade-dead-adventures-in-reversing-malicious-run-only-applescripts/"}], "id": "relationship--5f79680a-7b9f-47fd-bb81-025eb6368139", "modified": "2026-04-29T14:23:06.055Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2a59a237-1530-4d55-91f9-2aebf961cc37", "spec_version": "2.1", "target_ref": "attack-pattern--0533ab23-3f7d-463f-9bd8-634d27e4dee1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14679', 0, 72, '09-mitre-attack', 'retrieved', '4A834D66A0D8198BCEF6CAAB9DF7B35164C4E9418664076F8A74EFCEA048EA48', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
