VALUES ('doc-09-mitre-attack-p0-14681', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-04T06:47:57.845Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[macOS.OSAMiner](https://attack.mitre.org/software/S1048) has placed a [Stripped Payloads](https://attack.mitre.org/techniques/T1027/008) with a `plist` extension in the [Launch Agent](https://attack.mitre.org/techniques/T1543/001)''s folder. (Citation: SentinelLabs reversing run-only applescripts 2021)", "external_references": [{"description": "Phil Stokes. (2021, January 11). FADE DEAD | Adventures in Reversing Malicious Run-Only AppleScripts. Retrieved September 29, 2022.", "source_name": "SentinelLabs reversing run-only applescripts 2021", "url": "https://www.sentinelone.com/labs/fade-dead-adventures-in-reversing-malicious-run-only-applescripts/"}], "id": "relationship--9c59b652-09bc-4457-8342-949a87c1fafa", "modified": "2026-04-29T14:23:06.138Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2a59a237-1530-4d55-91f9-2aebf961cc37", "spec_version": "2.1", "target_ref": "attack-pattern--d10cbd34-42e3-45c0-84d2-535a09849584", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14681', 0, 78, '09-mitre-attack', 'retrieved', 'AD2C3CE312ECDE1ED5B4AE52451AE2EABD02173B9B93CECD345DE29418675967', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
