VALUES ('doc-09-mitre-attack-p0-14685', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LOWBALL](https://attack.mitre.org/software/S0042) command and control occurs via HTTPS over port 443.(Citation: FireEye admin@338)", "external_references": [{"description": "FireEye Threat Intelligence. (2015, December 1). China-based Cyber Threat Group Uses Dropbox for Malware Communications and Targets Hong Kong Media Outlets. Retrieved December 4, 2015.", "source_name": "FireEye admin@338", "url": "https://www.fireeye.com/blog/threat-research/2015/11/china-based-threat.html"}], "id": "relationship--12cc7738-bb90-4e77-a96d-8e4f312e07d4", "modified": "2026-04-29T14:23:05.930Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2a6f4c7b-e690-4cc7-ab6b-1f821fb6b80b", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14685', 0, 73, '09-mitre-attack', 'retrieved', 'D8303525C440C09D1C1C0FA2DDA8378F7888EECD6CCBF37D8BC7DF24A5E54C7F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
