VALUES ('doc-09-mitre-attack-p0-14762', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-19T19:59:30.921Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[J-magic](https://attack.mitre.org/software/S1203) can communicate back to send a challenge to C2 infrastructure over SSL.(Citation: Lumen J-Magic JAN 2025)", "external_references": [{"description": "Black Lotus Labs. (2025, January 23). The J-Magic Show: Magic Packets and Where to find them. Retrieved February 17, 2025.", "source_name": "Lumen J-Magic JAN 2025", "url": "https://blog.lumen.com/the-j-magic-show-magic-packets-and-where-to-find-them/"}], "id": "relationship--58470078-7abc-4c09-b304-e49cc515d412", "modified": "2026-04-29T14:23:06.046Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2ade64da-5114-42e4-9d56-335379cca561", "spec_version": "2.1", "target_ref": "attack-pattern--bf176076-b789-408e-8cba-7275e81c0ada", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14762', 0, 75, '09-mitre-attack', 'retrieved', 'C3E2828BBE32FA078996F66FD0DB09F11591BBB29A038A761A53928258609830', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
