VALUES ('doc-09-mitre-attack-p0-14763', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-19T19:08:02.210Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[J-magic](https://attack.mitre.org/software/S1203) can monitor TCP traffic for packets containing one of five different predefined parameters and will spawn a reverse shell if one of the parameters and the proper response string to a subsequent challenge is received.(Citation: Lumen J-Magic JAN 2025)", "external_references": [{"description": "Black Lotus Labs. (2025, January 23). The J-Magic Show: Magic Packets and Where to find them. Retrieved February 17, 2025.", "source_name": "Lumen J-Magic JAN 2025", "url": "https://blog.lumen.com/the-j-magic-show-magic-packets-and-where-to-find-them/"}], "id": "relationship--b3bd6363-e6dc-4c4a-ac41-2091127e1860", "modified": "2026-04-29T14:23:06.171Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2ade64da-5114-42e4-9d56-335379cca561", "spec_version": "2.1", "target_ref": "attack-pattern--451a9977-d255-43c9-b431-66de80130c8c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14763', 0, 98, '09-mitre-attack', 'retrieved', 'C0456FA679C5DD9D327DE92FA0777CCEF1734B1921408AB907AB2F9E299D779A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
