VALUES ('doc-09-mitre-attack-p0-14764', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-19T18:43:40.803Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[J-magic](https://attack.mitre.org/software/S1203) has a pcap listener function that can create an Extended Berkley Packet Filter (eBPF) on designated interfaces and ports.(Citation: Lumen J-Magic JAN 2025)", "external_references": [{"description": "Black Lotus Labs. (2025, January 23). The J-Magic Show: Magic Packets and Where to find them. Retrieved February 17, 2025.", "source_name": "Lumen J-Magic JAN 2025", "url": "https://blog.lumen.com/the-j-magic-show-magic-packets-and-where-to-find-them/"}], "id": "relationship--d5cd9334-11f1-42c8-b332-8a0aa884e254", "modified": "2026-04-29T14:23:06.217Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2ade64da-5114-42e4-9d56-335379cca561", "spec_version": "2.1", "target_ref": "attack-pattern--3257eb21-f9a7-4430-8de1-d8b6e288f529", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14764', 0, 82, '09-mitre-attack', 'retrieved', 'C98EFF2D233A9EC9B8F1F4E4748628268E1AACEF1EE3A4C0A86FA314FCB57E63', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
