VALUES ('doc-09-mitre-attack-p0-14776', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-22T16:39:04.536Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOOKWORM](https://attack.mitre.org/software/S1226) has created a hidden window when conducting key logging and clipboard theft through its KBLogger.dll module.(Citation: Unit42 Bookworm Nov2015)", "external_references": [{"description": "Robert Falcone, Mike Scott, Juan Cortes. (2015, November 10). Bookworm Trojan: A Model of Modular Architecture. Retrieved July 21, 2025.", "source_name": "Unit42 Bookworm Nov2015", "url": "https://unit42.paloaltonetworks.com/bookworm-trojan-a-model-of-modular-architecture/"}], "id": "relationship--74a577af-ef40-4767-a80a-68222fff5126", "modified": "2026-04-29T14:23:06.085Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2ceddaf9-b16a-4f8b-b252-bcccccd3d79f", "spec_version": "2.1", "target_ref": "attack-pattern--cbb66055-0325-4111-aca0-40547b6ad5b0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14776', 0, 77, '09-mitre-attack', 'retrieved', '37C31465DE7806E896821BABDDAA539DCD8BC1C33DEFDB020A815DC4C0889212', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
