VALUES ('doc-09-mitre-attack-p0-14778', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-21T19:48:45.470Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOOKWORM](https://attack.mitre.org/software/S1226) has used DLL side-loading to execute the malicious payload. (Citation: Broadcom)(Citation: Palo Alto Networks, Unit 42) [BOOKWORM](https://attack.mitre.org/software/S1226) has also side-loaded DLL components into a legitimate process, including Microsoft Malware Protection `MsMpEng.exe` and Kaspersky Anti-Virus `ushata.exe`.(Citation: Unit42 Bookworm Nov2015)", "external_references": [{"description": "Broadcom Protection Bulletins. (2025, February 20). Bookworm malware linked to Fireant (aka Stately Tarurus) activity observed in Southeast Asia. Retrieved July 21, 2025.", "source_name": "Broadcom", "url": "https://www.broadcom.com/support/security-center/protection-bulletin/bookworm-malware-linked-to-fireant-aka-stately-tarurus-activity-observed-in-southeast-asia"}, {"description": "Robert Falcone, Mike Scott, Juan Cortes. (2015, November 10). Bookworm Trojan: A Model of Modular Architecture. Retrieved July 21, 2025.", "source_name": "Unit42 Bookworm Nov2015", "url": "https://unit42.paloaltonetworks.com/bookworm-trojan-a-model-of-modular-architecture/"}, {"description": "Robert Falcone. (2025, February 20). Stately Taurus Activity in Southeast Asia Links to Bookworm Malware. Retrieved July 21, 2025.", "source_name": "Palo Alto Networks, Unit 42", "url": "https://unit42.paloaltonetworks.com/stately-taurus-uses-bookworm-malware/"}], "id": "relationship--80d10b7f-e1eb-4ad0-821c-b35d177418f4", "modified": "2026-04-29T14:23:06.101Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2ceddaf9-b16a-4f8b-b252-bcccccd3d79f", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14778', 0, 152, '09-mitre-attack', 'retrieved', '3F74547DF317F6DAB0C2C0CEA3A3A64EC4615B0D0CB0548C06F33797B9DAE308', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
