VALUES ('doc-09-mitre-attack-p0-14779', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-22T16:40:24.967Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOOKWORM](https://attack.mitre.org/software/S1226) has created services that attempt to resemble legitimate services to include a service named `Microsoft Windows DeviceSync Service`.(Citation: Unit42 Bookworm Nov2015)", "external_references": [{"description": "Robert Falcone, Mike Scott, Juan Cortes. (2015, November 10). Bookworm Trojan: A Model of Modular Architecture. Retrieved July 21, 2025.", "source_name": "Unit42 Bookworm Nov2015", "url": "https://unit42.paloaltonetworks.com/bookworm-trojan-a-model-of-modular-architecture/"}], "id": "relationship--848da21a-d33d-4dc4-a948-4b0e30963d30", "modified": "2026-04-29T14:23:06.106Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2ceddaf9-b16a-4f8b-b252-bcccccd3d79f", "spec_version": "2.1", "target_ref": "attack-pattern--7bdca9d5-d500-4d7d-8c52-5fd47baf4c0c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14779', 0, 79, '09-mitre-attack', 'retrieved', 'EA9EEAD6B1C21900B99A60249FD6B3EDA71218EC4B9A3FA4728AB4D67292FB2B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
