INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-14781', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-21T19:37:20.100Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOOKWORM](https://attack.mitre.org/software/S1226) has used various Windows API calls during execution and defense evasion.(Citation: Broadcom) (Citation: Palo Alto Networks, Unit 42) [BOOKWORM](https://attack.mitre.org/software/S1226) has created a buffer on the heap using `HeapCreate` and `HeapAlloc` which allows for copying of shell code and then execution on the heap is initiated through callback function of legitimate API functions such as `EnumChildWindows` or `EnumSystemLanguageGroupsA`. (Citation: Palo Alto Networks, Unit 42)", "external_references": [{"description": "Broadcom Protection Bulletins. (2025, February 20). Bookworm malware linked to Fireant (aka Stately Tarurus) activity observed in Southeast Asia. Retrieved July 21, 2025.", "source_name": "Broadcom", "url": "https://www.broadcom.com/support/security-center/protection-bulletin/bookworm-malware-linked-to-fireant-aka-stately-tarurus-activity-observed-in-southeast-asia"}, {"description": "Robert Falcone. (2025, February 20). Stately Taurus Activity in Southeast Asia Links to Bookworm Malware. Retrieved July 21, 2025.", "source_name": "Palo Alto Networks, Unit 42", "url": "https://unit42.paloaltonetworks.com/stately-taurus-uses-bookworm-malware/"}], "id": "relationship--9093e0ad-88a0-4575-8c31-3da712820947", "modified": "2026-04-29T14:23:06.122Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2ceddaf9-b16a-4f8b-b252-bcccccd3d79f", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14781', 0, 150, '09-mitre-attack', 'retrieved', '1543692C7EB6B47912336CE0BF423C138E3B98EEAB0BF63E9FBBF98116C31B0E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
