VALUES ('doc-09-mitre-attack-p0-14782', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-22T16:37:16.552Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOOKWORM](https://attack.mitre.org/software/S1226) has used encryption and compression algorithms to obfuscate the traffic between the system and C2 server, methods observed included RC4, AES, XOR with 0x5a, and LZO. (Citation: Unit42 Bookworm Nov2015)", "external_references": [{"description": "Robert Falcone, Mike Scott, Juan Cortes. (2015, November 10). Bookworm Trojan: A Model of Modular Architecture. Retrieved July 21, 2025.", "source_name": "Unit42 Bookworm Nov2015", "url": "https://unit42.paloaltonetworks.com/bookworm-trojan-a-model-of-modular-architecture/"}], "id": "relationship--92dc384d-3644-4b75-834d-d85c33aec69b", "modified": "2026-04-29T14:23:06.125Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2ceddaf9-b16a-4f8b-b252-bcccccd3d79f", "spec_version": "2.1", "target_ref": "attack-pattern--24bfaeba-cb0d-4525-b3dc-507c77ecec41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14782', 0, 88, '09-mitre-attack', 'retrieved', 'FD3AE1C311AE64C362CFC849120A3326EDC0281F777E60694EC0C55EB9017F0F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
