VALUES ('doc-09-mitre-attack-p0-14803', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Before being appended to image files, [HAMMERTOSS](https://attack.mitre.org/software/S0037) commands are encrypted with a key composed of both a hard-coded value and a string contained on that day''s tweet. To decrypt the commands, an investigator would need access to the intended malware sample, the day''s tweet, and the image file containing the command.(Citation: FireEye APT29)", "external_references": [{"description": "FireEye Labs. (2015, July). HAMMERTOSS: Stealthy Tactics Define a Russian Cyber Threat Group. Retrieved November 17, 2024.", "source_name": "FireEye APT29", "url": "https://services.google.com/fh/files/misc/rpt-apt29-hammertoss-stealthy-tactics-define-en.pdf"}], "id": "relationship--3ebc8829-f260-4d75-817a-cd23a4ebb194", "modified": "2026-04-29T14:23:06.010Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2daa14d6-cbf3-4308-bb8e-213c324a08e4", "spec_version": "2.1", "target_ref": "attack-pattern--24bfaeba-cb0d-4525-b3dc-507c77ecec41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14803', 0, 106, '09-mitre-attack', 'retrieved', '60F99E33711497FF6D24EE9F036CD50874B81CF3B1B3BD8C9438FF3A219CAD6B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
