VALUES ('doc-09-mitre-attack-p0-14830', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CosmicDuke](https://attack.mitre.org/software/S0050) exfiltrates collected files over FTP or WebDAV. Exfiltration servers can be separately configured from C2 servers.(Citation: F-Secure Cosmicduke)", "external_references": [{"description": "F-Secure Labs. (2014, July). COSMICDUKE Cosmu with a twist of MiniDuke. Retrieved July 3, 2014.", "source_name": "F-Secure Cosmicduke", "url": "https://blog.f-secure.com/wp-content/uploads/2019/10/CosmicDuke.pdf"}], "id": "relationship--3d4dabc2-3bee-409a-a05d-e107677cfdc7", "modified": "2026-04-29T14:23:06.008Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2eb9b131-d333-4a48-9eb4-d8dec46c19ee", "spec_version": "2.1", "target_ref": "attack-pattern--fb8d023d-45be-47e9-bc51-f56bcae6435b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14830', 0, 70, '09-mitre-attack', 'retrieved', '0309A4F727FE26C5E9DD63B670091C1C10265623CFDF76FDEEA0DEF30E178DF0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
