VALUES ('doc-09-mitre-attack-p0-14831', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CosmicDuke](https://attack.mitre.org/software/S0050) steals user files from network shared drives with file extensions and keywords that match a predefined list.(Citation: F-Secure Cosmicduke)", "external_references": [{"description": "F-Secure Labs. (2014, July). COSMICDUKE Cosmu with a twist of MiniDuke. Retrieved July 3, 2014.", "source_name": "F-Secure Cosmicduke", "url": "https://blog.f-secure.com/wp-content/uploads/2019/10/CosmicDuke.pdf"}], "id": "relationship--3e7c9978-4db1-4ee1-ae27-640acee5a543", "modified": "2026-04-29T14:23:06.010Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2eb9b131-d333-4a48-9eb4-d8dec46c19ee", "spec_version": "2.1", "target_ref": "attack-pattern--ae676644-d2d2-41b7-af7e-9bed1b55898c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14831', 0, 71, '09-mitre-attack', 'retrieved', '73DD4C0A736E2848B93793D2EE5D290053767CDA369DE29417F8A6DDB81BCD96', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
