VALUES ('doc-09-mitre-attack-p0-14832', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CosmicDuke](https://attack.mitre.org/software/S0050) collects user credentials, including passwords, for various programs including popular instant messaging applications and email clients as well as WLAN keys.(Citation: F-Secure The Dukes)", "external_references": [{"description": "F-Secure Labs. (2015, September 17). The Dukes: 7 years of Russian cyberespionage. Retrieved December 10, 2015.", "source_name": "F-Secure The Dukes", "url": "https://www.f-secure.com/documents/996508/1030745/dukes_whitepaper.pdf"}], "id": "relationship--4d7add6f-ebd5-477f-9958-a5176835da2e", "modified": "2026-04-29T14:23:06.031Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2eb9b131-d333-4a48-9eb4-d8dec46c19ee", "spec_version": "2.1", "target_ref": "attack-pattern--3fc9b85a-2862-4363-a64d-d692e3ffbee0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14832', 0, 78, '09-mitre-attack', 'retrieved', '42C4C3AF45F819F6D6CFFC37504D063310A7519432D499C3F2EF8163CB99AD00', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
