VALUES ('doc-09-mitre-attack-p0-14852', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-13T15:21:03.208Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[EnvyScout](https://attack.mitre.org/software/S0634) can determine whether the ISO payload was received by a Windows or iOS device.(Citation: MSTIC Nobelium Toolset May 2021)", "external_references": [{"description": "MSTIC. (2021, May 28). Breaking down NOBELIUM’s latest early-stage toolset. Retrieved August 4, 2021.", "source_name": "MSTIC Nobelium Toolset May 2021", "url": "https://www.microsoft.com/security/blog/2021/05/28/breaking-down-nobeliums-latest-early-stage-toolset/"}], "id": "relationship--055a15db-2f5b-4c61-821e-36de6f83a90b", "modified": "2026-04-29T14:23:05.910Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2f8229dc-da94-41c6-89ba-b5b6c32f6b7d", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14852', 0, 73, '09-mitre-attack', 'retrieved', 'DF77F7CE74D1A76FEF43031A670AA8E2A18B526C11BA08E712C672C60D1A771A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
