VALUES ('doc-09-mitre-attack-p0-14871', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SslMM](https://attack.mitre.org/software/S0058) has a hard-coded primary and backup C2 string.(Citation: Baumgartner Naikon 2015)", "external_references": [{"description": "Baumgartner, K., Golovkin, M.. (2015, May). The MsnMM Campaigns: The Earliest Naikon APT Campaigns. Retrieved April 10, 2019.", "source_name": "Baumgartner Naikon 2015", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2018/03/07205555/TheNaikonAPT-MsnMM1.pdf"}], "id": "relationship--329678a6-eb6b-499b-90a8-059d1cf1a35f", "modified": "2026-04-29T14:23:05.985Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--2fb26586-2b53-4b9a-ad4f-2b3bcb9a2421", "spec_version": "2.1", "target_ref": "attack-pattern--f24faf46-3b26-4dbb-98f2-63460498e433", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14871', 0, 67, '09-mitre-attack', 'retrieved', 'A027105E22C0C636616B771AB4E20E89406E449ED30EB635C700377BF827B304', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
