VALUES ('doc-09-mitre-attack-p0-14917', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-17T23:31:33.420Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gomir](https://attack.mitre.org/software/S1198) periodically communicates to its command and control infrastructure through HTTP POST requests.(Citation: Symantec Troll Stealer 2024)", "external_references": [{"description": "Symantec Threat Hunter Team. (2024, May 16). Springtail: New Linux Backdoor Added to Toolkit. Retrieved January 17, 2025.", "source_name": "Symantec Troll Stealer 2024", "url": "https://www.security.com/threat-intelligence/springtail-kimsuky-backdoor-espionage"}], "id": "relationship--8a52753e-bd37-4b1f-8886-4b2e474acf1d", "modified": "2026-04-29T14:23:06.114Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3128c86d-bd0d-445c-850f-96abf68fbfc3", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14917', 0, 73, '09-mitre-attack', 'retrieved', '2F662EA913C42BBF38B9A04BCBD1F74C560A4C4FA49C9C282B7A8CC7CF2ADFA0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
