VALUES ('doc-09-mitre-attack-p0-14920', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-17T23:36:30.493Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gomir](https://attack.mitre.org/software/S1198) collects network information on infected systems such as listing interface names, MAC and IP addresses, and IPv6 addresses.(Citation: Symantec Troll Stealer 2024)", "external_references": [{"description": "Symantec Threat Hunter Team. (2024, May 16). Springtail: New Linux Backdoor Added to Toolkit. Retrieved January 17, 2025.", "source_name": "Symantec Troll Stealer 2024", "url": "https://www.security.com/threat-intelligence/springtail-kimsuky-backdoor-espionage"}], "id": "relationship--c6b5a499-a6d6-4b6c-b24f-93844630f84d", "modified": "2026-04-29T14:23:06.197Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3128c86d-bd0d-445c-850f-96abf68fbfc3", "spec_version": "2.1", "target_ref": "attack-pattern--707399d6-ab3e-4963-9315-d9d3818cd6a0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14920', 0, 79, '09-mitre-attack', 'retrieved', 'E674E74AB30FC67EE5A4CE238D59CB696988470EB3E6FEEC94CEFB24B48F49BD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
