VALUES ('doc-09-mitre-attack-p0-14922', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-17T23:28:04.410Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gomir](https://attack.mitre.org/software/S1198) checks the effective group ID of its process when initially executed to determine if it is in group 0, denoting superuser privileges in Linux environments.(Citation: Symantec Troll Stealer 2024)", "external_references": [{"description": "Symantec Threat Hunter Team. (2024, May 16). Springtail: New Linux Backdoor Added to Toolkit. Retrieved January 17, 2025.", "source_name": "Symantec Troll Stealer 2024", "url": "https://www.security.com/threat-intelligence/springtail-kimsuky-backdoor-espionage"}], "id": "relationship--d8dc23f0-67a2-4cf8-a22c-ee63b5631715", "modified": "2026-04-29T14:23:06.221Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3128c86d-bd0d-445c-850f-96abf68fbfc3", "spec_version": "2.1", "target_ref": "attack-pattern--a01bf75f-00b2-4568-a58f-565ff9bf202b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14922', 0, 86, '09-mitre-attack', 'retrieved', 'D028E633416DFF320C50AD6A4DFE04693672B80453C7C03A3FCCD759D38F28B5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
