VALUES ('doc-09-mitre-attack-p0-14923', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-17T23:29:47.832Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gomir](https://attack.mitre.org/software/S1198) deletes its original executable and terminates its original process after creating a systemd service.(Citation: Symantec Troll Stealer 2024)", "external_references": [{"description": "Symantec Threat Hunter Team. (2024, May 16). Springtail: New Linux Backdoor Added to Toolkit. Retrieved January 17, 2025.", "source_name": "Symantec Troll Stealer 2024", "url": "https://www.security.com/threat-intelligence/springtail-kimsuky-backdoor-espionage"}], "id": "relationship--f299a89c-59f1-41a6-a5d5-425edfe26f25", "modified": "2026-04-29T14:23:06.255Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3128c86d-bd0d-445c-850f-96abf68fbfc3", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14923', 0, 75, '09-mitre-attack', 'retrieved', 'A1AEBECC797113DA937E0AF7AD4D783B11B3120C687D5DC9CE0FC0EBB1AAE4A4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
