VALUES ('doc-09-mitre-attack-p0-14958', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-26T19:23:01.984Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Emotet](https://attack.mitre.org/software/S0367) has leveraged the Admin$, C$, and IPC$ shares for lateral movement. (Citation: Malwarebytes Emotet Dec 2017)(Citation: Binary Defense Emotes Wi-Fi Spreader) ", "external_references": [{"description": "Binary Defense. (n.d.). Emotet Evolves With new Wi-Fi Spreader. Retrieved September 8, 2023.", "source_name": "Binary Defense Emotes Wi-Fi Spreader", "url": "https://www.binarydefense.com/resources/blog/emotet-evolves-with-new-wi-fi-spreader/"}, {"description": "Smith, A.. (2017, December 22). Protect your network from Emotet Trojan with Malwarebytes Endpoint Security. Retrieved January 17, 2019.", "source_name": "Malwarebytes Emotet Dec 2017", "url": "https://support.malwarebytes.com/docs/DOC-2295"}], "id": "relationship--1bc150db-66ca-4361-84a2-2dd0f104790f", "modified": "2026-04-29T14:23:05.942Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--32066e94-3112-48ca-b9eb-ba2b59d2f023", "spec_version": "2.1", "target_ref": "attack-pattern--4f9ca633-15c5-463c-9724-bdcd54fde541", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14958', 0, 102, '09-mitre-attack', 'retrieved', '05475500256A03DED4F4EB1E987413E38D4CB7BD889DD134B1A81F7BC1F4B605', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
