VALUES ('doc-09-mitre-attack-p0-14961', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-24T21:06:37.114Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Emotet](https://attack.mitre.org/software/S0367) can brute force a local admin password, then use it to facilitate lateral movement.(Citation: Malwarebytes Emotet Dec 2017)", "external_references": [{"description": "Smith, A.. (2017, December 22). Protect your network from Emotet Trojan with Malwarebytes Endpoint Security. Retrieved January 17, 2019.", "source_name": "Malwarebytes Emotet Dec 2017", "url": "https://support.malwarebytes.com/docs/DOC-2295"}], "id": "relationship--30930d8a-3c0d-41b2-a226-cccc56599bfd", "modified": "2026-04-29T14:23:05.978Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--32066e94-3112-48ca-b9eb-ba2b59d2f023", "spec_version": "2.1", "target_ref": "attack-pattern--fdc47f44-dd32-4b99-af5f-209f556f63c2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14961', 0, 76, '09-mitre-attack', 'retrieved', 'C2A4D3128A3F5485C7D8DD819ABDDD16715F6D6BDC93B84C3CB24D2E9632222E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
