VALUES ('doc-09-mitre-attack-p0-14962', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-26T17:48:52.119Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Emotet](https://attack.mitre.org/software/S0367) has been observed adding the downloaded payload to the HKEY_CURRENT_USER\\Software\\Microsoft\\Windows\\CurrentVersion\\Run key to maintain persistence.(Citation: Symantec Emotet Jul 2018)(Citation: US-CERT Emotet Jul 2018)(Citation: Picus Emotet Dec 2018)", "external_references": [{"description": "Symantec. (2018, July 18). The Evolution of Emotet: From Banking Trojan to Threat Distributor. Retrieved March 25, 2019.", "source_name": "Symantec Emotet Jul 2018", "url": "https://www.symantec.com/blogs/threat-intelligence/evolution-emotet-trojan-distributor"}, {"description": "US-CERT. (2018, July 20). Alert (TA18-201A) Emotet Malware. Retrieved March 25, 2019.", "source_name": "US-CERT Emotet Jul 2018", "url": "https://www.us-cert.gov/ncas/alerts/TA18-201A"}, {"description": "Özarslan, S. (2018, December 21). The Christmas Card you never wanted - A new wave of Emotet is back to wreak havoc. Retrieved March 25, 2019.", "source_name": "Picus Emotet Dec 2018", "url": "https://www.picussecurity.com/blog/the-christmas-card-you-never-wanted-a-new-wave-of-emotet-is-back-to-wreak-havoc.html"}], "id": "relationship--3236ca50-2342-455a-b258-6a085cae8fc2", "modified": "2026-04-29T14:23:05.983Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--32066e94-3112-48ca-b9eb-ba2b59d2f023", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14962', 0, 137, '09-mitre-attack', 'retrieved', 'E9F3C0683C08382B90E68F0BF13B1E9E1C34BB567E4C775830F4BE7D789D073D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
