VALUES ('doc-09-mitre-attack-p0-14963', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-26T19:23:02.037Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Emotet](https://attack.mitre.org/software/S0367) has been delivered by phishing emails containing links. (Citation: Trend Micro Banking Malware Jan 2019)(Citation: Kaspersky Emotet Jan 2019)(Citation: CIS Emotet Apr 2017)(Citation: Malwarebytes Emotet Dec 2017)(Citation: Symantec Emotet Jul 2018)(Citation: US-CERT Emotet Jul 2018)(Citation: Talos Emotet Jan 2019)(Citation: Talos Emotet Jan 2019)(Citation: Picus Emotet Dec 2018)", "external_references": [{"description": "Salvio, J.. (2014, June 27). New Banking Malware Uses Network Sniffing for Data Theft. Retrieved March 25, 2019.", "source_name": "Trend Micro Banking Malware Jan 2019", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/new-banking-malware-uses-network-sniffing-for-data-theft/"}, {"description": "Shulmin, A. . (2015, April 9). The Banking Trojan Emotet: Detailed Analysis. Retrieved March 25, 2019.", "source_name": "Kaspersky Emotet Jan 2019", "url": "https://securelist.com/the-banking-trojan-emotet-detailed-analysis/69560/"}, {"description": "CIS. (2017, April 28). Emotet Changes TTPs and Arrives in United States. Retrieved January 17, 2019.", "source_name": "CIS Emotet Apr 2017", "url": "https://www.cisecurity.org/blog/emotet-changes-ttp-and-arrives-in-united-states/"}, {"description": "Smith, A.. (2017, December 22). Protect your network from Emotet Trojan with Malwarebytes Endpoint Security. Retrieved January 17, 2019.", "source_name": "Malwarebytes Emotet Dec 2017", "url": "https://support.malwarebytes.com/docs/DOC-2295"}, {"description": "Symantec. (2018, July 18). The Evolution of Emotet: From Banking Trojan to Threat Distributor. Retrieved March 25, 2019.", "source_name": "Symantec Emotet Jul 2018", "url": "https://www.symantec.com/blogs/threat-intelligence/evolution-emotet-trojan-distributor"}, {"description": "US-CERT. (2018, July 20). Alert (TA18-201A) Emotet Malware. Retrieved March 25, 2019.", "source_name": "US-CERT Emotet Jul 2018", "url": "https://www.us-cert.gov/ncas/alerts/TA18-201A"}, {"description": "Brumaghin, E.. (2019, January 15). Emotet re-emerges after the holidays. Retrieved March 25, 2019.", "source_name": "Talos Emotet Jan 2019", "url": "https://blog.talosintelligence.com/2019/01/return-of-emotet.html"}, {"description": "Brumaghin, E.. (2019, January 15). Emotet re-emerges after the holidays. Retrieved March 25, 2019.", "source_name": "Talos Emotet Jan 2019", "url": "https://blog.talosintelligence.com/2019/01/return-of-emotet.html"}, {"description": "Özarslan, S. (2018, December 21). The Christmas Card you never wanted - A new wave of Emotet is back to wreak havoc. Retrieved March 25, 2019.", "source_name": "Picus Emotet Dec 2018", "url": "https://www.picussecurity.com/blog/the-christmas-card-you-never-wanted-a-new-wave-of-emotet-is-back-to-wreak-havoc.html"}], "id": "relationship--382b8780-edc3-477f-a7fa-3e6ba62397a2", "modified": "2026-04-29T14:23:05.997Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--32066e94-3112-48ca-b9eb-ba2b59d2f023", "spec_version": "2.1", "target_ref": "attack-pattern--2b742742-28c3-4e1b-bab7-8350d6300fa7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14963', 0, 305, '09-mitre-attack', 'retrieved', '5592A6EC14B9363743801A14CD081965B14FB0C555FC883CACBEAEB20DFDDE42', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
