VALUES ('doc-09-mitre-attack-p0-14964', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-29T21:07:31.485Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Emotet](https://attack.mitre.org/software/S0367) has used Google’s Protobufs to serialize data sent to and from the C2 server.(Citation: Binary Defense Emotes Wi-Fi Spreader) Additionally, [Emotet](https://attack.mitre.org/software/S0367) has used Base64 to encode data before sending to the C2 server.(Citation: Fortinet Emotet May 2017)", "external_references": [{"description": "Binary Defense. (n.d.). Emotet Evolves With new Wi-Fi Spreader. Retrieved September 8, 2023.", "source_name": "Binary Defense Emotes Wi-Fi Spreader", "url": "https://www.binarydefense.com/resources/blog/emotet-evolves-with-new-wi-fi-spreader/"}, {"description": "Xiaopeng Zhang. (2017, May 3). Deep Analysis of New Emotet Variant – Part 1. Retrieved April 1, 2019.", "source_name": "Fortinet Emotet May 2017", "url": "https://www.fortinet.com/blog/threat-research/deep-analysis-of-new-emotet-variant-part-1.html"}], "id": "relationship--48a7db34-eee7-4358-918b-0cc802aaec03", "modified": "2026-04-29T14:23:06.024Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--32066e94-3112-48ca-b9eb-ba2b59d2f023", "spec_version": "2.1", "target_ref": "attack-pattern--04fd5427-79c7-44ea-ae13-11b24778ff1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14964', 0, 116, '09-mitre-attack', 'retrieved', 'E9C6D2591E69DE82BFF08C6662F8AF75B3DE7E525534430AA59FA3EE08D5DC51', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
