VALUES ('doc-09-mitre-attack-p0-14965', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-29T19:44:43.762Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Emotet](https://attack.mitre.org/software/S0367) has enumerated non-hidden network shares using `WNetEnumResourceW`. (Citation: Binary Defense Emotes Wi-Fi Spreader)", "external_references": [{"description": "Binary Defense. (n.d.). Emotet Evolves With new Wi-Fi Spreader. Retrieved September 8, 2023.", "source_name": "Binary Defense Emotes Wi-Fi Spreader", "url": "https://www.binarydefense.com/resources/blog/emotet-evolves-with-new-wi-fi-spreader/"}], "id": "relationship--491dc622-fa43-4015-b24a-8ec8d8f5a376", "modified": "2026-04-29T14:23:06.025Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--32066e94-3112-48ca-b9eb-ba2b59d2f023", "spec_version": "2.1", "target_ref": "attack-pattern--3489cfc5-640f-4bb3-a103-9137b97de79f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14965', 0, 66, '09-mitre-attack', 'retrieved', 'B5F0DE1AC5A18D3B708CEE4580777B191FB2B1808B98C82CB8FF50C368CB3C34', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
