VALUES ('doc-09-mitre-attack-p0-14970', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-29T21:06:02.849Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Emotet](https://attack.mitre.org/software/S0367) has been observed leveraging a module that can scrape email addresses from Outlook.(Citation: CIS Emotet Dec 2018)(Citation: IBM IcedID November 2017)(Citation: Binary Defense Emotes Wi-Fi Spreader)", "external_references": [{"description": "Binary Defense. (n.d.). Emotet Evolves With new Wi-Fi Spreader. Retrieved September 8, 2023.", "source_name": "Binary Defense Emotes Wi-Fi Spreader", "url": "https://www.binarydefense.com/resources/blog/emotet-evolves-with-new-wi-fi-spreader/"}, {"description": "CIS. (2018, December 12). MS-ISAC Security Primer- Emotet. Retrieved March 25, 2019.", "source_name": "CIS Emotet Dec 2018", "url": "https://www.cisecurity.org/white-papers/ms-isac-security-primer-emotet/"}, {"description": "Kessem, L., et al. (2017, November 13). New Banking Trojan IcedID Discovered by IBM X-Force Research. Retrieved July 14, 2020.", "source_name": "IBM IcedID November 2017", "url": "https://securityintelligence.com/new-banking-trojan-icedid-discovered-by-ibm-x-force-research/"}], "id": "relationship--76d0dcb7-046a-40d7-80ec-e0e571359f51", "modified": "2026-04-29T14:23:06.088Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--32066e94-3112-48ca-b9eb-ba2b59d2f023", "spec_version": "2.1", "target_ref": "attack-pattern--1608f3e1-598a-42f4-a01a-2e252e81728f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14970', 0, 127, '09-mitre-attack', 'retrieved', '3B79304EF42E665A06746204602CA8CFE447976E2A296424C3273C74C6AB18FC', 'v1', '{"source_id": "09-mitr