VALUES ('doc-09-mitre-attack-p0-14973', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-26T17:48:52.143Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Emotet](https://attack.mitre.org/software/S0367) has used Powershell to retrieve the malicious payload and download additional resources like [Mimikatz](https://attack.mitre.org/software/S0002). (Citation: Symantec Emotet Jul 2018)(Citation: Trend Micro Emotet Jan 2019)(Citation: Picus Emotet Dec 2018)(Citation: Red Canary Emotet Feb 2019)(Citation: Carbon Black Emotet Apr 2019)", "external_references": [{"description": "Symantec. (2018, July 18). The Evolution of Emotet: From Banking Trojan to Threat Distributor. Retrieved March 25, 2019.", "source_name": "Symantec Emotet Jul 2018", "url": "https://www.symantec.com/blogs/threat-intelligence/evolution-emotet-trojan-distributor"}, {"description": "Trend Micro. (2019, January 16). Exploring Emotet''s Activities . Retrieved March 25, 2019.", "source_name": "Trend Micro Emotet Jan 2019", "url": "https://documents.trendmicro.com/assets/white_papers/ExploringEmotetsActivities_Final.pdf"}, {"description": "Özarslan, S. (2018, December 21). The Christmas Card you never wanted - A new wave of Emotet is back to wreak havoc. Retrieved March 25, 2019.", "source_name": "Picus Emotet Dec 2018", "url": "https://www.picussecurity.com/blog/the-christmas-card-you-never-wanted-a-new-wave-of-emotet-is-back-to-wreak-havoc.html"}, {"description": "Donohue, B.. (2019, February 13). https://redcanary.com/blog/stopping-emotet-before-it-moves-laterally/. Retrieved March 25, 2019.", "source_name": "Red Canary Emotet Feb 2019", "url": "https://redcanary.com/blog/stopping-emotet-before-it-moves-laterally/"}, {"description": "Lee, S.. (2019, April 24). Emotet Using WMI to Launch PowerShell Encoded Code. Retrieved May 24, 2019.", "source_name": "Carbon Black Emotet Apr 2019", "url": "https://www.carbonblack.com/2019/04/24/cb-tau-threat-intelligence-notification-emotet-utilizing-wmi-to-launch-powershell-encoded-code/"}], "id": "relationship--7b458295-8e67-4f1f-acde-3316ae2e061e", "modified": "2026-04-29T14:23:06.094Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--32066e94-3112-48ca-b9eb-ba2b59d2f023", "spec_version": "2.1", "target_ref": "attack-pattern--970a3432-3237-47ad-bcca-7d8cbb217736", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14973', 0, 196, '09-mitre-attack', 'retrieved', '0E79AD8A40CAE1476223CCE848AF4647A18A13CA390B012DA825441A85195B11', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
