VALUES ('doc-09-mitre-attack-p0-14993', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-08T15:50:22.096Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Emotet](https://attack.mitre.org/software/S0367) can extract names of all locally reachable Wi-Fi networks and then perform a brute-force attack to spread to new networks.(Citation: Binary Defense Emotes Wi-Fi Spreader)", "external_references": [{"description": "Binary Defense. (n.d.). Emotet Evolves With new Wi-Fi Spreader. Retrieved September 8, 2023.", "source_name": "Binary Defense Emotes Wi-Fi Spreader", "url": "https://www.binarydefense.com/resources/blog/emotet-evolves-with-new-wi-fi-spreader/"}], "id": "relationship--fe8a52b2-b1b8-4193-a637-abd9ec219e6a", "modified": "2026-04-29T14:23:06.271Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--32066e94-3112-48ca-b9eb-ba2b59d2f023", "spec_version": "2.1", "target_ref": "attack-pattern--494ab9f0-36e0-4b06-b10d-57285b040a06", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14993', 0, 78, '09-mitre-attack', 'retrieved', '699FE95B61F5E0605823BC36F3B262EE312C64787F5B33F2E44067C89ECE5FE3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
