VALUES ('doc-09-mitre-attack-p0-14995', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-26T17:48:52.214Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Emotet](https://attack.mitre.org/software/S0367) has been seen exploiting SMB via a vulnerability exploit like EternalBlue (MS17-010) to achieve lateral movement and propagation.(Citation: Symantec Emotet Jul 2018)(Citation: US-CERT Emotet Jul 2018)(Citation: Secureworks Emotet Nov 2018)(Citation: Red Canary Emotet Feb 2019) ", "external_references": [{"description": "Donohue, B.. (2019, February 13). https://redcanary.com/blog/stopping-emotet-before-it-moves-laterally/. Retrieved March 25, 2019.", "source_name": "Red Canary Emotet Feb 2019", "url": "https://redcanary.com/blog/stopping-emotet-before-it-moves-laterally/"}, {"description": "Mclellan, M.. (2018, November 19). Lazy Passwords Become Rocket Fuel for Emotet SMB Spreader. Retrieved March 25, 2019.", "source_name": "Secureworks Emotet Nov 2018", "url": "https://www.secureworks.com/blog/lazy-passwords-become-rocket-fuel-for-emotet-smb-spreader"}, {"description": "Symantec. (2018, July 18). The Evolution of Emotet: From Banking Trojan to Threat Distributor. Retrieved March 25, 2019.", "source_name": "Symantec Emotet Jul 2018", "url": "https://www.symantec.com/blogs/threat-intelligence/evolution-emotet-trojan-distributor"}, {"description": "US-CERT. (2018, July 20). Alert (TA18-201A) Emotet Malware. Retrieved March 25, 2019.", "source_name": "US-CERT Emotet Jul 2018", "url": "https://www.us-cert.gov/ncas/alerts/TA18-201A"}], "id": "relationship--6cb2f741-eedb-4b1d-8d84-7823f0095d44", "modified": "2026-08-04T20:30:55.906Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--32066e94-3112-48ca-b9eb-ba2b59d2f023", "spec_version": "2.1", "target_ref": "attack-pattern--9db0cf3a-a3c9-4012-8268-123b9db6fd82",