VALUES ('doc-09-mitre-attack-p0-15010', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-25T15:05:23.714Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Olympic Destroyer](https://attack.mitre.org/software/S0365) utilizes [PsExec](https://attack.mitre.org/software/S0029) to help propagate itself across a network.(Citation: Talos Olympic Destroyer 2018)", "external_references": [{"description": "Mercer, W. and Rascagneres, P. (2018, February 12). Olympic Destroyer Takes Aim At Winter Olympics. Retrieved March 14, 2019.", "source_name": "Talos Olympic Destroyer 2018", "url": "https://blog.talosintelligence.com/2018/02/olympic-destroyer.html"}], "id": "relationship--c992481b-fe93-416d-b8a3-c5ed752c17f4", "modified": "2026-04-29T14:23:06.201Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3249e92a-870b-426d-8790-ba311c1abfb4", "spec_version": "2.1", "target_ref": "attack-pattern--f1951e8a-500e-4a26-8803-76d95c4554b4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15010', 0, 72, '09-mitre-attack', 'retrieved', 'B376E5CDB6FC4239E74747C8F47BDF001428AE715CF8AB564BFA0758D1364F31', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
