VALUES ('doc-09-mitre-attack-p0-15011', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-25T15:05:23.691Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Olympic Destroyer](https://attack.mitre.org/software/S0365) uses [PsExec](https://attack.mitre.org/software/S0029) to interact with the ADMIN$ network share to execute commands on remote systems.(Citation: Talos Olympic Destroyer 2018)(Citation: PsExec Russinovich)", "external_references": [{"description": "Mercer, W. and Rascagneres, P. (2018, February 12). Olympic Destroyer Takes Aim At Winter Olympics. Retrieved March 14, 2019.", "source_name": "Talos Olympic Destroyer 2018", "url": "https://blog.talosintelligence.com/2018/02/olympic-destroyer.html"}, {"description": "Russinovich, M. (2004, June 28). PsExec. Retrieved December 17, 2015.", "source_name": "PsExec Russinovich", "url": "http://windowsitpro.com/systems-management/psexec"}], "id": "relationship--ddf5cb3a-6cfa-40c8-8992-396329632f14", "modified": "2026-04-29T14:23:06.228Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3249e92a-870b-426d-8790-ba311c1abfb4", "spec_version": "2.1", "target_ref": "attack-pattern--4f9ca633-15c5-463c-9724-bdcd54fde541", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15011', 0, 96, '09-mitre-attack', 'retrieved', 'A23E4DC19151D64336270AF90C0667FCE19D85D9254FACF279F21A99D8C5ABFD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
