VALUES ('doc-09-mitre-attack-p0-15015', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-31T22:47:56.199Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOLDMOVE](https://attack.mitre.org/software/S1184) calls the signal function to ignore the signals SIGCHLD, SIGHIP, and SIGPIPE prior to starting primary logic.(Citation: Google Cloud BOLDMOVE 2023)", "external_references": [{"description": "Scott Henderson, Cristiana Kittner, Sarah Hawley & Mark Lechtik, Google Cloud. (2023, January 19). Suspected Chinese Threat Actors Exploiting FortiOS Vulnerability (CVE-2022-42475). Retrieved December 31, 2024.", "source_name": "Google Cloud BOLDMOVE 2023", "url": "https://cloud.google.com/blog/topics/threat-intelligence/chinese-actors-exploit-fortios-flaw/"}], "id": "relationship--28868afd-06fb-4f9d-a925-b8e035dfde15", "modified": "2026-04-29T14:23:05.960Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--325fa466-4a2a-45a0-acc6-f6bed9b45ebe", "spec_version": "2.1", "target_ref": "attack-pattern--4a2975db-414e-4c0c-bd92-775987514b4b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15015', 0, 86, '09-mitre-attack', 'retrieved', '1AE86609DAAF932E048705352B12B166F573E38E89C92C28C21EEDEC7F803214', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
