VALUES ('doc-09-mitre-attack-p0-15018', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-31T22:47:00.929Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOLDMOVE](https://attack.mitre.org/software/S1184) uses the WolfSSL library to implement SSL encryption for command and control communication.(Citation: Google Cloud BOLDMOVE 2023)", "external_references": [{"description": "Scott Henderson, Cristiana Kittner, Sarah Hawley & Mark Lechtik, Google Cloud. (2023, January 19). Suspected Chinese Threat Actors Exploiting FortiOS Vulnerability (CVE-2022-42475). Retrieved December 31, 2024.", "source_name": "Google Cloud BOLDMOVE 2023", "url": "https://cloud.google.com/blog/topics/threat-intelligence/chinese-actors-exploit-fortios-flaw/"}], "id": "relationship--88e6ab9b-6804-46be-8080-7e92bd076761", "modified": "2026-04-29T14:23:06.112Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--325fa466-4a2a-45a0-acc6-f6bed9b45ebe", "spec_version": "2.1", "target_ref": "attack-pattern--bf176076-b789-408e-8cba-7275e81c0ada", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15018', 0, 82, '09-mitre-attack', 'retrieved', '78EAC9F33D0500B83930A07CE4D4452F5912E4479921FA6FEF06CE61AB491C51', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
