VALUES ('doc-09-mitre-attack-p0-15019', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-31T22:51:05.314Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOLDMOVE](https://attack.mitre.org/software/S1184) contains a watchdog-like feature that monitors a particular file for modification. If modification is detected, the legitimate file is backed up and replaced with a trojanized file to allow for persistence through likely system upgrades.(Citation: Google Cloud BOLDMOVE 2023)", "external_references": [{"description": "Scott Henderson, Cristiana Kittner, Sarah Hawley & Mark Lechtik, Google Cloud. (2023, January 19). Suspected Chinese Threat Actors Exploiting FortiOS Vulnerability (CVE-2022-42475). Retrieved December 31, 2024.", "source_name": "Google Cloud BOLDMOVE 2023", "url": "https://cloud.google.com/blog/topics/threat-intelligence/chinese-actors-exploit-fortios-flaw/"}], "id": "relationship--8b35ba04-fdad-4265-a1e8-e089a79baf4d", "modified": "2026-04-29T14:23:06.115Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--325fa466-4a2a-45a0-acc6-f6bed9b45ebe", "spec_version": "2.1", "target_ref": "attack-pattern--960c3c86-1480-4d72-b4e0-8c242e84a5c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15019', 0, 104, '09-mitre-attack', 'retrieved', '575E7C13597D98218CC4E590BCA45E679BB618787F270739E6EBE2C43FA9A7CA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
