VALUES ('doc-09-mitre-attack-p0-15059', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-14T14:29:38.196Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Tomiris](https://attack.mitre.org/software/S0671) can use HTTP to establish C2 communications.(Citation: Kaspersky Tomiris Sep 2021)", "external_references": [{"description": "Kwiatkoswki, I. and Delcher, P. (2021, September 29). DarkHalo After SolarWinds: the Tomiris connection. Retrieved December 27, 2021.", "source_name": "Kaspersky Tomiris Sep 2021", "url": "https://securelist.com/darkhalo-after-solarwinds-the-tomiris-connection/104311/"}], "id": "relationship--30565d66-2743-4e39-81ce-bc861149ce1e", "modified": "2026-04-29T14:23:05.977Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--327b3a25-9e60-4431-b3b6-93b9c64eacbc", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15059', 0, 68, '09-mitre-attack', 'retrieved', 'FC1870F363DEA9B3690489610A2784B0D9DABEFEB401CC49390C646030A79706', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
