VALUES ('doc-09-mitre-attack-p0-15060', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-12-29T15:08:44.529Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Tomiris](https://attack.mitre.org/software/S0671) has used `SCHTASKS /CREATE /SC DAILY /TN StartDVL /TR \"[path to self]\" /ST 10:00` to establish persistence.(Citation: Kaspersky Tomiris Sep 2021)", "external_references": [{"description": "Kwiatkoswki, I. and Delcher, P. (2021, September 29). DarkHalo After SolarWinds: the Tomiris connection. Retrieved December 27, 2021.", "source_name": "Kaspersky Tomiris Sep 2021", "url": "https://securelist.com/darkhalo-after-solarwinds-the-tomiris-connection/104311/"}], "id": "relationship--43ae357d-d0f8-4cdc-a9d6-0f10f603707c", "modified": "2026-04-29T14:23:06.018Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--327b3a25-9e60-4431-b3b6-93b9c64eacbc", "spec_version": "2.1", "target_ref": "attack-pattern--005a06c6-14bf-4118-afa0-ebcd8aebb0c9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15060', 0, 78, '09-mitre-attack', 'retrieved', 'EA543FE0D9B939D1D446576077FBF0C83FBDAA281F4A706AC10FA6B2483CFE34', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
