VALUES ('doc-09-mitre-attack-p0-15100', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-16T08:59:14.944Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DUSTTRAP](https://attack.mitre.org/software/S1159) can identify and enumerate victim system network shares.(Citation: Google Cloud APT41 2024)", "external_references": [{"description": "Mike Stokkel et al. (2024, July 18). APT41 Has Arisen From the DUST. Retrieved September 16, 2024.", "source_name": "Google Cloud APT41 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/apt41-arisen-from-dust"}], "id": "relationship--ff27aa33-f4da-424e-be51-ade535b359b3", "modified": "2026-04-29T14:23:06.271Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--33139388-de0c-49ff-862a-041c315b142d", "spec_version": "2.1", "target_ref": "attack-pattern--3489cfc5-640f-4bb3-a103-9137b97de79f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15100', 0, 68, '09-mitre-attack', 'retrieved', 'BDD59605A8F95F00D3F4ACBA598477050A46A89A856589E45812D863FF9D386F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
