VALUES ('doc-09-mitre-attack-p0-15101', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T22:21:21.233Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DynoWiper](https://attack.mitre.org/software/S9038) has used the Microsoft Windows native `ExitWindowsEx()` function to log off the interactive user and shutdown the system.(Citation: CERT Polska)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}], "id": "relationship--13ff8433-97c7-40c3-a082-812453731bf2", "modified": "2026-04-29T14:23:05.931Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--34057cb6-0a56-48a3-92e5-3af1357808da", "spec_version": "2.1", "target_ref": "attack-pattern--ff73aa03-0090-4464-83ac-f89e233c02bc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15101', 0, 73, '09-mitre-attack', 'retrieved', 'BC8466D395BF93219C3C93BF5A73E3A82861B0A40833E47BEBE8C12E365BE9CC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
