VALUES ('doc-09-mitre-attack-p0-15104', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T22:14:58.899Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DynoWiper](https://attack.mitre.org/software/S9038) has used the Microsoft Windows native `GetLogicalDrives()` and `GetDriveType()` functions to enumerate all the drives visible to the system.(Citation: CERT Polska)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}], "id": "relationship--501b58a3-5315-4415-8e4a-b2ee65db5013", "modified": "2026-04-29T14:23:06.035Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--34057cb6-0a56-48a3-92e5-3af1357808da", "spec_version": "2.1", "target_ref": "attack-pattern--f2514ae4-4e9b-4f26-a5ba-c4ae85fe93c3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15104', 0, 74, '09-mitre-attack', 'retrieved', '62147FF69EC577A6C63CE471DEBB4D288C5B04362FAABDF2E79B8D890A567C4A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
