VALUES ('doc-09-mitre-attack-p0-15110', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-07T18:46:08.811Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Turian](https://attack.mitre.org/software/S0647) has the ability to use /bin/sh to execute commands.(Citation: ESET BackdoorDiplomacy Jun 2021)", "external_references": [{"description": "Adam Burgher. (2021, June 10). BackdoorDiplomacy: Upgrading from Quarian to Turian. Retrieved September 1, 2021", "source_name": "ESET BackdoorDiplomacy Jun 2021", "url": "https://www.welivesecurity.com/2021/06/10/backdoordiplomacy-upgrading-quarian-turian/"}], "id": "relationship--0f363688-a168-4e9f-94e6-75142875c802", "modified": "2026-04-29T14:23:05.924Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--350f12cf-fd3b-4dad-b323-14b943090df4", "spec_version": "2.1", "target_ref": "attack-pattern--a9d4b653-6915-42af-98b2-5758c4ceee56", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15110', 0, 67, '09-mitre-attack', 'retrieved', 'C034007322BED6528418E4D5F5BB76F2625DB92B51F7BAC1BD95C4574A7C5549', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
