VALUES ('doc-09-mitre-attack-p0-15134', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-10-04T14:31:53.915Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BADHATCH](https://attack.mitre.org/software/S1081) can copy a large byte array of 64-bit shellcode into process memory and execute it with a call to `CreateThread`.(Citation: Gigamon BADHATCH Jul 2019)", "external_references": [{"description": "Savelesky, K., et al. (2019, July 23). ABADBABE 8BADFOOD: Discovering BADHATCH and a Detailed Look at FIN8''s Tooling. Retrieved September 8, 2021.", "source_name": "Gigamon BADHATCH Jul 2019", "url": "https://blog.gigamon.com/2019/07/23/abadbabe-8badf00d-discovering-badhatch-and-a-detailed-look-at-fin8s-tooling/"}], "id": "relationship--04a55a4d-7888-4e52-8d6f-6befbc82f6f2", "modified": "2026-04-29T14:23:05.909Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3553b49d-d4ae-4fb6-ab17-0adbc520c888", "spec_version": "2.1", "target_ref": "attack-pattern--4933e63b-9b77-476e-ab29-761bc5b7d15a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15134', 0, 85, '09-mitre-attack', 'retrieved', '820782208CB12CB7E9C958E3C748E12CA6E39758C9B94F6041A070763E7AE432', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
