VALUES ('doc-09-mitre-attack-p0-15261', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Prikormka](https://attack.mitre.org/software/S0113) encodes C2 traffic with Base64.(Citation: ESET Operation Groundbait)", "external_references": [{"description": "Cherepanov, A.. (2016, May 17). Operation Groundbait: Analysis of a surveillance toolkit. Retrieved May 18, 2016.", "source_name": "ESET Operation Groundbait", "url": "http://www.welivesecurity.com/wp-content/uploads/2016/05/Operation-Groundbait.pdf"}], "id": "relationship--9cf37d0b-a23d-4514-961d-94d1cc6e2bef", "modified": "2026-04-29T14:23:06.139Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--37cc7eb6-12e3-467b-82e8-f20f2cc73c69", "spec_version": "2.1", "target_ref": "attack-pattern--04fd5427-79c7-44ea-ae13-11b24778ff1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15261', 0, 62, '09-mitre-attack', 'retrieved', 'DE050CA6AEFE503A115B0E6DD2539E5A838BD2850ED50C8FB989EDF627323DCF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
