VALUES ('doc-09-mitre-attack-p0-15264', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Prikormka](https://attack.mitre.org/software/S0113) creates a directory, %USERPROFILE%\\AppData\\Local\\SKC\\ , which is used to store collected log files.(Citation: ESET Operation Groundbait)", "external_references": [{"description": "Cherepanov, A.. (2016, May 17). Operation Groundbait: Analysis of a surveillance toolkit. Retrieved May 18, 2016.", "source_name": "ESET Operation Groundbait", "url": "http://www.welivesecurity.com/wp-content/uploads/2016/05/Operation-Groundbait.pdf"}], "id": "relationship--df207207-01b2-456b-9dc4-7afd5ffeeb46", "modified": "2026-04-29T14:23:06.229Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--37cc7eb6-12e3-467b-82e8-f20f2cc73c69", "spec_version": "2.1", "target_ref": "attack-pattern--1c34f7aa-9341-4a48-bfab-af22e51aca6c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15264', 0, 70, '09-mitre-attack', 'retrieved', 'A6DB4F0835A3EA4A777A54B13E4E44C024493A8EBD37F784408ADFECB24ACF78', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
