VALUES ('doc-09-mitre-attack-p0-15294', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-08-06T14:59:16.541Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PUBLOAD](https://attack.mitre.org/software/S1228) has identified internet connectivity details through commands such as `tracert -h 5 -4 google.com` and `curl http://myip.ipip.net`.(Citation: Trend Micro MUSTANG PANDA PUBLOAD HIUPAN SEPTEMBER 2024)", "external_references": [{"description": "Lenart Bermejo, Sunny Lu, Ted Lee. (2024, September 9). Earth Preta Evolves its Attacks with New Malware and Strategies. Retrieved August 4, 2025.", "source_name": "Trend Micro MUSTANG PANDA PUBLOAD HIUPAN SEPTEMBER 2024", "url": "https://www.trendmicro.com/en_us/research/24/i/earth-preta-new-malware-and-strategies.html"}], "id": "relationship--cdbb0dc8-23e3-4dad-a2a8-52240353f587", "modified": "2026-04-29T14:23:06.206Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3824852d-1957-4712-9da0-38143723c060", "spec_version": "2.1", "target_ref": "attack-pattern--132d5b37-aac5-4378-a8dc-3127b18a73dc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15294', 0, 91, '09-mitre-attack', 'retrieved', 'F01BFD2E4A4EB050B41D575E68B8D1D170A139514F5EA59F994410E17A54E069', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
