VALUES ('doc-09-mitre-attack-p0-15305', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-12-16T00:09:20.339Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SystemBC](https://attack.mitre.org/software/S9001) has used `cmd.exe` to execute VBS scripts, BAT scripts and CMD scripts.(Citation: SophosGnGal_SystemBC_Dec2020)", "external_references": [{"description": "Gallagher, S., Gn, S. (2020, December 16). Ransomware operators use SystemBC RAT as off-the-shelf Tor backdoor. Retrieved May 16, 2025.", "source_name": "SophosGnGal_SystemBC_Dec2020", "url": "https://news.sophos.com/en-us/2020/12/16/systembc/"}], "id": "relationship--14c87d77-834d-4f0a-abaa-984c7e2a67d6", "modified": "2026-04-29T14:23:05.932Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--39643fb9-00c1-4a45-85e5-801a3f2665d1", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15305', 0, 69, '09-mitre-attack', 'retrieved', '7C2F5B6EE0ABB855F75EEA7A4BACF87DC4A1A7AA3D0E2F8370D0D8CE0FFA470C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
