VALUES ('doc-09-mitre-attack-p0-15307', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-12-16T00:11:51.642Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SystemBC](https://attack.mitre.org/software/S9001) has leveraged the time of the device to create a text file with a filename that uses the function of `uniqid(time()).‘.txt`, consisting of the 10 character UNIX timestamp and 13 hexadecimal characters.(Citation: TrumanKroll_SYSTEMBCServer_Jan2024)", "external_references": [{"description": "Truman, D. (2024, January 19). Inside the SYSTEMBC Command-and-Control Server. Retrieved June 18, 2025.", "source_name": "TrumanKroll_SYSTEMBCServer_Jan2024", "url": "https://www.kroll.com/en/publications/cyber/inside-the-systembc-malware-server"}], "id": "relationship--17efbe51-6bd0-458f-98f3-f841b105d7bf", "modified": "2026-04-29T14:23:05.937Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--39643fb9-00c1-4a45-85e5-801a3f2665d1", "spec_version": "2.1", "target_ref": "attack-pattern--f3c544dc-673c-4ef3-accb-53229f1ae077", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15307', 0, 83, '09-mitre-attack', 'retrieved', '3AE6D4A86E541E276CD58ACC9C5B07723BF88629701E7C2BBFEA326147221D8F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
