VALUES ('doc-09-mitre-attack-p0-15308', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-12-15T23:35:36.069Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SystemBC](https://attack.mitre.org/software/S9001) has downloaded additional files for execution on the victim’s machine.(Citation: SophosGnGal_SystemBC_Dec2020)(Citation: TrumanKroll_SYSTEMBCServer_Jan2024) The server component of [SystemBC](https://attack.mitre.org/software/S9001) has the ability to send additional files to victim machines.(Citation: TrumanKroll_SYSTEMBCServer_Jan2024)", "external_references": [{"description": "Gallagher, S., Gn, S. (2020, December 16). Ransomware operators use SystemBC RAT as off-the-shelf Tor backdoor. Retrieved May 16, 2025.", "source_name": "SophosGnGal_SystemBC_Dec2020", "url": "https://news.sophos.com/en-us/2020/12/16/systembc/"}, {"description": "Truman, D. (2024, January 19). Inside the SYSTEMBC Command-and-Control Server. Retrieved June 18, 2025.", "source_name": "TrumanKroll_SYSTEMBCServer_Jan2024", "url": "https://www.kroll.com/en/publications/cyber/inside-the-systembc-malware-server"}], "id": "relationship--2eb1f662-5901-4bbe-b45b-54c8dfc5e20e", "modified": "2026-04-29T14:23:05.968Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--39643fb9-00c1-4a45-85e5-801a3f2665d1", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15308', 0, 103, '09-mitre-attack', 'retrieved', '4FF9DF9D50AD59B3F2416C10FC33550DACAA68CB3FE984EE216825DB036ABB17', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
