VALUES ('doc-09-mitre-attack-p0-15311', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-12-17T18:47:47.009Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SystemBC](https://attack.mitre.org/software/S9001) has encoded with XOR and encrypted with RC4 its beacon.(Citation: Lumen_SystemBC_Sept2025)", "external_references": [{"description": "Black Lotus Labs . (2025, September 18). SystemBC: Bringing the noise. Retrieved December 15, 2025.", "source_name": "Lumen_SystemBC_Sept2025", "url": "https://blog.lumen.com/systembc-bringing-the-noise/"}], "id": "relationship--4802a823-0a51-47c2-aabe-369a2430ba95", "modified": "2026-04-29T14:23:06.023Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--39643fb9-00c1-4a45-85e5-801a3f2665d1", "spec_version": "2.1", "target_ref": "attack-pattern--ad255bfe-a9e6-4b52-a258-8d3462abe842", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15311', 0, 62, '09-mitre-attack', 'retrieved', '42CF0043D61DECB7FCCAA0F247E0CF9A37A4AB4F3F0673BC911204AD187E5C6B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
