VALUES ('doc-09-mitre-attack-p0-15312', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-12-16T00:00:33.284Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SystemBC](https://attack.mitre.org/software/S9001) has used DNS servers to resolve .bit domains to C2 infrastructure.(Citation: HarmonProofpoint_SystemBC_Aug2019)", "external_references": [{"description": "Harmon, K., et al. (2019, August 1). SystemBC is like Christmas in July for SOCKS5 Malware and Exploit Kits . Retrieved June 13, 2025.", "source_name": "HarmonProofpoint_SystemBC_Aug2019", "url": "https://www.proofpoint.com/us/threat-insight/post/systembc-christmas-july-socks5-malware-and-exploit-kits"}], "id": "relationship--5fac7323-462e-4ef5-848b-5ff54833a67e", "modified": "2026-04-29T14:23:06.055Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--39643fb9-00c1-4a45-85e5-801a3f2665d1", "spec_version": "2.1", "target_ref": "attack-pattern--1996eef1-ced3-4d7f-bf94-33298cabbf72", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15312', 0, 72, '09-mitre-attack', 'retrieved', '44658F4B28D72FBBE66885D6E9D44D56ADC34FD8281AEF238C49E5528EE67136', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
