VALUES ('doc-09-mitre-attack-p0-15313', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-12-15T23:35:09.582Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The server component of [SystemBC](https://attack.mitre.org/software/S9001) has used various TCP ports for C2 communication.(Citation: TrumanKroll_SYSTEMBCServer_Jan2024)", "external_references": [{"description": "Truman, D. (2024, January 19). Inside the SYSTEMBC Command-and-Control Server. Retrieved June 18, 2025.", "source_name": "TrumanKroll_SYSTEMBCServer_Jan2024", "url": "https://www.kroll.com/en/publications/cyber/inside-the-systembc-malware-server"}], "id": "relationship--62bfecb7-7388-410a-afb3-fcd60fbc0af9", "modified": "2026-04-29T14:23:06.059Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--39643fb9-00c1-4a45-85e5-801a3f2665d1", "spec_version": "2.1", "target_ref": "attack-pattern--b18eae87-b469-4e14-b454-b171b416bc18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15313', 0, 63, '09-mitre-attack', 'retrieved', 'ED7D93D6886AC466382C80A1CAD2F766CFA8C601741F29B38A90927B0FF6203F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
