VALUES ('doc-09-mitre-attack-p0-15315', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-12-16T00:02:07.112Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SystemBC](https://attack.mitre.org/software/S9001) has collected username , build number and serial number, then sent the information to the C2 server.(Citation: SophosGnGal_SystemBC_Dec2020)(Citation: AhnLab_SystemBC_Apr2022) [SystemBC](https://attack.mitre.org/software/S9001) has also gathered device name, operating system, and processor type.(Citation: HarmonProofpoint_SystemBC_Aug2019)", "external_references": [{"description": "AhnLab. (2022, April 4). SystemBC Being Used by Various Attackers . Retrieved June 18, 2025.", "source_name": "AhnLab_SystemBC_Apr2022", "url": "https://asec.ahnlab.com/en/33600/"}, {"description": "Gallagher, S., Gn, S. (2020, December 16). Ransomware operators use SystemBC RAT as off-the-shelf Tor backdoor. Retrieved May 16, 2025.", "source_name": "SophosGnGal_SystemBC_Dec2020", "url": "https://news.sophos.com/en-us/2020/12/16/systembc/"}, {"description": "Harmon, K., et al. (2019, August 1). SystemBC is like Christmas in July for SOCKS5 Malware and Exploit Kits . Retrieved June 13, 2025.", "source_name": "HarmonProofpoint_SystemBC_Aug2019", "url": "https://www.proofpoint.com/us/threat-insight/post/systembc-christmas-july-socks5-malware-and-exploit-kits"}], "id": "relationship--670b59d4-25c6-4171-a36b-efb27155cc95", "modified": "2026-04-29T14:23:06.065Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--39643fb9-00c1-4a45-85e5-801a3f2665d1", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15315', 0, 136, '09-mitre-attack', 'retrieved', 'A30D85B04AD588BDC056F28CD8A88E524F21A9853F5CD5A758105284D03E6163', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
