VALUES ('doc-09-mitre-attack-p0-15321', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-12-16T00:13:31.515Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SystemBC](https://attack.mitre.org/software/S9001) has leveraged the Sleep functions before and after commands to ensure execution using the hexadecimal values within commands to include `Sleep(0x2710u)` that waits 10 seconds, and `Sleep(0xEA60u)` for 60 seconds.(Citation: SophosGnGal_SystemBC_Dec2020) ", "external_references": [{"description": "Gallagher, S., Gn, S. (2020, December 16). Ransomware operators use SystemBC RAT as off-the-shelf Tor backdoor. Retrieved May 16, 2025.", "source_name": "SophosGnGal_SystemBC_Dec2020", "url": "https://news.sophos.com/en-us/2020/12/16/systembc/"}], "id": "relationship--95c85b70-64f6-410f-82fd-c9dc1c154a4f", "modified": "2026-04-29T14:23:06.129Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--39643fb9-00c1-4a45-85e5-801a3f2665d1", "spec_version": "2.1", "target_ref": "attack-pattern--a1df809c-7d0e-459f-8fe5-25474bab770b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15321', 0, 88, '09-mitre-attack', 'retrieved', '5ADF35FA19EF756B38E97E9BA554609B23C0ED561F49E26035489217302E150F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
