VALUES ('doc-09-mitre-attack-p0-15322', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-12-16T00:06:54.104Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SystemBC](https://attack.mitre.org/software/S9001) has used raw TCP on non-standard ports, such as 4044, for C2 communications and for HTTP communications, which include downloading binaries.(Citation: SophosGnGal_SystemBC_Dec2020)(Citation: AhnLab_SystemBC_Apr2022)", "external_references": [{"description": "AhnLab. (2022, April 4). SystemBC Being Used by Various Attackers . Retrieved June 18, 2025.", "source_name": "AhnLab_SystemBC_Apr2022", "url": "https://asec.ahnlab.com/en/33600/"}, {"description": "Gallagher, S., Gn, S. (2020, December 16). Ransomware operators use SystemBC RAT as off-the-shelf Tor backdoor. Retrieved May 16, 2025.", "source_name": "SophosGnGal_SystemBC_Dec2020", "url": "https://news.sophos.com/en-us/2020/12/16/systembc/"}], "id": "relationship--c8c8c0bc-0240-4cd1-aff3-edbe19a91e57", "modified": "2026-04-29T14:23:06.200Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--39643fb9-00c1-4a45-85e5-801a3f2665d1", "spec_version": "2.1", "target_ref": "attack-pattern--c21d5a77-d422-4a69-acd7-2c53c1faa34b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15322', 0, 99, '09-mitre-attack', 'retrieved', '9953E4F8E0B494C0B79BD1B4E5088E379E8BEEF8FDAE1FC2166388B0BB30461A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
