VALUES ('doc-09-mitre-attack-p0-15324', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-29T21:03:42.045Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gootloader](https://attack.mitre.org/software/S1138) can use IP geolocation to determine if the person browsing to a compromised site is within a targeted territory such as the US, Canada, Germany, and South Korea.(Citation: SentinelOne Gootloader June 2021)", "external_references": [{"description": "Pirozzi, A. (2021, June 16). Gootloader: ‘Initial Access as a Service’ Platform Expands Its Search for High Value Targets. Retrieved May 28, 2024.", "source_name": "SentinelOne Gootloader June 2021", "url": "https://www.sentinelone.com/labs/gootloader-initial-access-as-a-service-platform-expands-its-search-for-high-value-targets/"}], "id": "relationship--02653ee2-6907-4fb5-b946-9cbd4377ad64", "modified": "2026-04-29T14:23:05.906Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--396c18b9-26fb-4435-8589-fb856502e4c4", "spec_version": "2.1", "target_ref": "attack-pattern--c877e33f-1df6-40d6-b1e7-ce70f16f4979", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15324', 0, 94, '09-mitre-attack', 'retrieved', '5D94C83AD28078FD44E092C64C1DD5A972C6EE8234C46C002AC5C7C4247D4E4B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
