VALUES ('doc-09-mitre-attack-p0-15355', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-16T17:57:21.394Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PingPull](https://attack.mitre.org/software/S1031) has the ability to exfiltrate stolen victim data through its C2 channel.(Citation: Unit 42 PingPull Jun 2022)", "external_references": [{"description": "Unit 42. (2022, June 13). GALLIUM Expands Targeting Across Telecommunications, Government and Finance Sectors With New PingPull Tool. Retrieved August 7, 2022.", "source_name": "Unit 42 PingPull Jun 2022", "url": "https://unit42.paloaltonetworks.com/pingpull-gallium/"}], "id": "relationship--f72dda85-719d-4e6f-bac8-2589934ae6dd", "modified": "2026-04-29T14:23:06.261Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3a0f6128-0a01-421d-8eca-e57d8671b1f1", "spec_version": "2.1", "target_ref": "attack-pattern--92d7da27-2d91-488e-a00c-059dc162766d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15355', 0, 79, '09-mitre-attack', 'retrieved', 'AF2F9D7CD8A4227C64C78D2F0ACEBF921BC167195E36C81E6D0E33235C8D850F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
